action.transformation:
(
  $inventory := number;
  $isNilOrEmpty($inventory) ? undefined :
  (

    $flowResult := $executeFlow(
      "inventoryTransactionRouter",
      {
        "REQUEST": {
          "INVENTORY": [
            {
              "number": $inventory
            }
          ]
        },
        "ACTION": "VALIDATE"
      }
    );

    $isNilOrEmpty($flowResult.data.LOCAL.inventory) ? 
        $throw("Inventory: " & $inventory & " does not exist" & $flowResult)


    :
    [
     $components.Form33.fn.loadData({"filter":{"number": {"_in": [$inventory]}}}),
      $components.Container67.fn.show(),
      $components.Form37.fn.setValue('mergeQuantity', 0),
      $components.Form37.fn.setValue('mergeAll', false),
      $components.Form37.fn.setValue('printer', undefined)
    ]
  )
)

transforms.post:
[
 $addNotificationMessage("Merge Request Information", {
    "message": "The merge request has gone through succesfully, below is the information for this operation.",
    "severity": "info",
    "data": {
      "additionalInformation": "Merge from Inventory: " & result.RESPONSE.removeFromInventory.number & "\n" & $join(
          [
            $count([result.RESPONSE.addToInventory.number]) > 1 ? "Merge to Inventory:" : "Merge to Inventory:",
            $join(
              [
                result.RESPONSE.addToInventory.number
              ],
              ", "
            )
          ],
          "  "
        ) & "\n" & "Quantity Merged: " & result.RESPONSE.mergeQuantity
    }
  }),
  $components.Form37.fn.setValue('mergeQuantity', 0),
  $components.Form37.fn.setValue('mergeAll', false),
  $components.Form37.fn.setValue('printer', undefined),
  $components.Form32.fn.setValue('number', ""),
  $components.Form34.fn.setValue('number', "")
]

